function numIslands(grid) {
  const rows = grid.length, cols = grid[0].length;
  let count = 0;
  function dfs(r, c) {
    // Bounds + non-land guard at TOP — lets callers recurse blindly.
    if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] !== "1") return;
    grid[r][c] = "0";        // sink in-place — acts as "visited"
    dfs(r + 1, c);
    dfs(r - 1, c);
    dfs(r, c + 1);
    dfs(r, c - 1);
  }
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      // Each unsunk "1" starts one island; DFS sinks the whole component.
      if (grid[r][c] === "1") { count++; dfs(r, c); }
    }
  }
  return count;
}
// Time O(R*C), Space O(R*C) recursion in worst case

