function numIslands(grid) {
  const rows = grid.length, cols = grid[0].length;
  const parent = Array.from({length: rows * cols}, (_, i) => i);
  function find(x) {
    while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
    return x;
  }
  // Start count = number of land cells; each successful union drops it by 1.
  let count = 0;
  for (let r = 0; r < rows; r++)
    for (let c = 0; c < cols; c++)
      if (grid[r][c] === "1") count++;
  // Only need to check right + down neighbors to avoid double-processing each edge.
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] !== "1") continue;
      for (const [dr, dc] of [[1,0],[0,1]]) {
        const nr = r + dr, nc = c + dc;
        if (nr < rows && nc < cols && grid[nr][nc] === "1") {
          const ra = find(r * cols + c), rb = find(nr * cols + nc);
          if (ra !== rb) { parent[ra] = rb; count--; }
        }
      }
    }
  }
  return count;
}
